package com.yeyamo_mobile.api.discovery_service.application;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.discovery_service.application.port.*;
@Service public class DiscoveryQueryService{private final DiscoverySearchPort search;private final DiscoveryCachePort cache;public DiscoveryQueryService(DiscoverySearchPort s,DiscoveryCachePort c){search=s;cache=c;}@Transactional(readOnly=true)public DiscoveryPage search(DiscoverySearch criteria){return cache.get(criteria).orElseGet(()->load(criteria));}private DiscoveryPage load(DiscoverySearch c){List<com.yeyamo_mobile.api.discovery_service.domain.model.DiscoveryDocument>found=search.search(c,c.size()+1);boolean next=found.size()>c.size();List<com.yeyamo_mobile.api.discovery_service.domain.model.DiscoveryDocument>items=next?List.copyOf(found.subList(0,c.size())):List.copyOf(found);DiscoveryPage p=new DiscoveryPage(c.page(),c.size(),next,items,Instant.now());cache.put(c,p);return p;}}
